        if filtered.rfind(',') > filtered.rfind('.'):
            # comma is decimal, dot is thousand
            dec_sep = ','
            th_sep = '.'
        else:
            dec_sep = '.'
            th_sep = ','
        cleaned_num = filtered.replace(th_sep, '')
        if dec_sep == ',':
