import json
import math
import re
import numpy as np
import pandas as pd


def parse_amount(val: str, paren_mode: str = "enclosed") -> float:
    """Parse amount_str into base_amount based on rules 1-7."""
    if pd.isna(val):
        return np.nan
    s = str(val).strip()
    if not s:
        return np.nan

    # Rule 3: Treat as negative if CR token, enclosed in parens, or minus sign
    is_neg = False
    if "CR" in s or "-" in s:
        is_neg = True
    if paren_mode == "enclosed":
        if s.startswith("(") and s.endswith(")"):
            is_neg = True

    # Rule 4: Remove tokens C1 and C2, strip letters and spaces, keep digits, comma, dot
    s_clean = re.sub(r"C[12]", "", s)
    filtered = re.sub(r"[^0-9,\.]", "", s_clean)
    if not filtered:
        return np.nan

    has_comma = "," in filtered
    has_dot = "." in filtered

    # Rule 5 & 6: Determine decimal separator using last-separator rule & two digits rule
    if has_comma and has_dot:
        if filtered.rfind(",") > filtered.rfind("."):
            dec_sep, th_sep = ",", "."
        else:
            dec_sep, th_sep = ".", ","
        cleaned_num = filtered.replace(th_sep, "")
        if dec_sep == ",":
            cleaned_num = cleaned_num.replace(",", ".")
    elif has_comma:
        digits_after = len(filtered.split(",")[-1])
        if digits_after == 2:
            cleaned_num = filtered.replace(",", ".")
        else:
            cleaned_num = filtered.replace(",", "")
    elif has_dot:
        digits_after = len(filtered.split(".")[-1])
        if digits_after == 2:
            cleaned_num = filtered
        else:
            cleaned_num = filtered.replace(".", "")
    else:
        cleaned_num = filtered

    # Rule 7: Parse as float
    try:
        amt = float(cleaned_num)
        return -amt if is_neg else amt
    except Exception:
        return np.nan


def parse_notes(notes):
    """Parse notes for items, adj_pct, fee, waive."""
    items = None
    adj_pct = 0.0
    fee = 0.0
    waive = False

    if pd.isna(notes):
        return items, adj_pct, fee, waive

    parts = [p.strip() for p in str(notes).split(";") if p.strip()]
    for p in parts:
        if "=" not in p:
            continue
        k, v = p.split("=", 1)
        k, v = k.strip().lower(), v.strip()
        if k == "items":
            try:
                items = int(v)
            except Exception:
                pass
        elif k == "adj":
            try:
                if v.endswith("%"):
                    adj_pct = float(v[:-1]) / 100.0
                else:
                    adj_pct = float(v) / 100.0
            except Exception:
                pass
        elif k == "fee":
            try:
                fee = float(v)
            except Exception:
                pass
        elif k == "waive":
            waive = v.lower() == "true"

    return items, adj_pct, fee, waive


def answer() -> list[str]:
    # Read CSV
    df = pd.read_csv("/app/dataset/data.csv")
    df["orig_idx"] = df.index

    # Parse amount_str and notes
    df["base_amount"] = [parse_amount(v) for v in df["amount_str"]]
    notes_parsed = [parse_notes(n) for n in df["notes"]]
    df["items"] = [x[0] for x in notes_parsed]
    df["adj_pct"] = [x[1] for x in notes_parsed]
    df["fee"] = [x[2] for x in notes_parsed]
    df["waive"] = [x[3] for x in notes_parsed]

    # Compute net
    def calc_net(row):
        if pd.isna(row["base_amount"]):
            return np.nan
        if row["waive"]:
            return 0.0
        return row["base_amount"] * (1.0 + row["adj_pct"]) + row["fee"]

    df["net"] = df.apply(calc_net, axis=1)

    # Deduplication per record_id:
    # Keep one row per record_id by choosing the latest event_time,
    # breaking ties by preferring the version with a real net result, then earlier file order.
    def get_best_row(group):
        best, best_key = None, None
        for _, r in group.iterrows():
            et = r["event_time"]
            has_et = 1 if pd.notna(et) else 0
            et_val = et if pd.notna(et) else ""
            real_net = 1 if (pd.notna(r["net"]) and np.isfinite(r["net"])) else 0
            idx = r["orig_idx"]
            key = (has_et, et_val, real_net, -idx)
            if best_key is None or key > best_key:
                best_key = key
                best = r
        return best

    rows = []
    for _, g in df.groupby("record_id"):
        rows.append(get_best_row(g))
    deduped = pd.DataFrame(rows)

    # Filtering:
    # Keep only rows with non-missing event_time,
    # event_time between 2025-10-01 00:00:00 and 2025-12-31 23:59:59 inclusive,
    # channel != "phone" (case-insensitive), and finite net
    cond = (
        deduped["event_time"].notna()
        & (deduped["event_time"] >= "2025-10-01T00:00:00Z")
        & (deduped["event_time"] <= "2025-12-31T23:59:59Z")
        & (deduped["channel"].str.strip().str.lower() != "phone")
        & deduped["net"].notna()
        & np.isfinite(deduped["net"])
    )
    filtered = deduped[cond].copy()
    filtered["month"] = filtered["event_time"].str[:7]

    # Robust z-score within each (region, month) group
    robust_z_list = []
    for idx, r in filtered.iterrows():
        reg, m = r["region"], r["month"]
        g_vals = filtered[
            (filtered["region"] == reg) & (filtered["month"] == m)
        ]["net"]
        med = g_vals.median()
        mad = (g_vals - med).abs().median()
        if mad == 0:
            rz = 0.0
        else:
            rz = 0.6745 * (r["net"] - med) / mad
        robust_z_list.append(rz)

    filtered["robust_z"] = robust_z_list
    filtered["abs_robust_z"] = filtered["robust_z"].abs()

    # items_eff and anomaly_score
    filtered["items_eff"] = filtered["items"].apply(
        lambda x: max(1, x) if (pd.notna(x) and x is not None) else 1
    )
    filtered["anomaly_score"] = filtered["abs_robust_z"] * np.log1p(
        filtered["items_eff"]
    )

    # Rank rows by anomaly_score descending, then abs(robust_z) descending,
    # then event_time descending, then record_id ascending using mergesort
    filtered = filtered.sort_values(
        by=["anomaly_score", "abs_robust_z", "event_time", "record_id"],
        ascending=[False, False, False, True],
        kind="mergesort",
    )

    return filtered["record_id"].head(10).tolist()


if __name__ == "__main__":
    with open("/app/answer.json", "w") as f:
        json.dump(answer(), f, default=list)
